# -*- coding: utf-8 -*-
# Place in God's Storyline paragraphs, DRAFT for publisher review (not in repo).
CL = "One God, faithful across two programs that never merge."
MYST = "It does not speak of the Mystery, which was hid in God and not yet revealed (Rom. 16:25; Eph. 3:9)."
S = {}
S['genesis'] = ("Genesis (before Israel, and the head of Israel’s line)", "Genesis opens the Bible in two stages. Chapters 1–11 precede Israel and report creation, the fall, the flood and the nations (Gen. 1:1; 3:1–24; 6:5–8; 11:8–9). From Genesis 12 the line of promise begins, with the call of Abram, the promise of a land and a seed, and the family that became the nation (Gen. 12:1–3; 15:18; 17:7; 50:24). The book advances promise and judgment, and the Law has not yet been given. Genesis advances the redemptive storyline by establishing the promise through which Israel’s future restoration and kingdom will come. It does not speak of the Mystery. The Body receives blessing through Christ alone, not through participation in the Abrahamic covenant. "+CL)
S['exodus'] = ("Israel’s line", "Exodus stands in Israel’s line at the point where the promise becomes a nation: the family of Jacob, grown in Egypt, is brought out under Moses and given the Law at Sinai (Ex. 12:41; 19:5–6; 20:1–2). The book carries the line through bondage, the Passover, the crossing of the sea and the wilderness, and closes with the tabernacle and the glory of the LORD filling it (Ex. 12:13; 14:21–22; 25:8; 40:34). Exodus advances Israel’s redemptive story by showing the LORD redeeming His covenant people by blood and power and setting His dwelling among them. The Law it gives is Israel’s; the Body is not under it (Rom. 6:14), and the book does not speak of the Mystery. "+CL)
S['leviticus'] = ("Israel’s line", "Leviticus stands in Israel’s line at Sinai, in the LORD’s word to Moses from the tabernacle for the children of Israel (Lev. 1:1). It gives the offerings, the priesthood, the laws of clean and unclean, the day of atonement, the feasts and the blessings and curses of the covenant (Lev. 16:30; 23:2; 26:12). Leviticus advances Israel’s redemptive story by setting out how a holy God can dwell among a sinful people: atonement by blood and a priesthood to carry it (Lev. 17:11; 16:30). Its worship is Israel’s own, tied to the tabernacle and the land, and it is not laid on the Body (Rom. 6:14). The book does not speak of the Mystery. "+CL)
S['numbers'] = ("Israel’s line", "Numbers stands in Israel’s line between Sinai and the land. The tribes are numbered and set around the tabernacle, and then the people murmur, refuse to go up, and wander forty years (Num. 1:1–3; 14:11, 33–34). The book carries the line through judgment, and also through mercy in the bronze serpent and the promise of a Star out of Jacob (Num. 21:8–9; 24:17). Numbers advances Israel’s redemptive story by preserving the nation under judgment and bringing a new generation to the edge of the land that was sworn to its fathers (Num. 27:18; 34:2). The nation, camp and inheritance it describes are Israel’s, and the book does not speak of the Mystery. "+CL)
S['deuteronomy'] = ("Israel’s line", "Deuteronomy stands in Israel’s line on the plains beside Jordan, in the last words of Moses “unto all Israel” before the land is entered (Deut. 1:1). He recalls the way from Horeb, restates the law, and sets before the people the blessing and the curse, the scattering and the gathering (Deut. 5:2; 11:26; 30:1–5). Deuteronomy advances Israel’s redemptive story by fixing the terms on which the nation’s later history is judged and by promising that the LORD will turn their captivity and gather them again (Deut. 30:3). Its covenant is Israel’s and the Body is not under it (Rom. 6:14). The book does not speak of the Mystery. "+CL)
S['joshua'] = ("Israel’s line", "Joshua stands in Israel’s line at the entrance to the land, after the death of Moses (Josh. 1:2). The people cross the Jordan, take Jericho, fight the battles of the conquest, divide the land by tribe, and renew the covenant at Shechem (Josh. 3:17; 6:20; 13:7; 24:25). Joshua advances Israel’s redemptive story by bringing the promise of the land into history: the LORD gives Israel the land He sware to their fathers (Josh. 21:43–45). The inheritance is Israel’s, in the land, and the Body’s hope is not measured by it. The book does not speak of the Mystery. "+CL)
S['judges'] = ("Israel’s line", "Judges stands in Israel’s line in the land after Joshua, in days when “there was no king in Israel” (Judg. 17:6; 21:25). The book records the repeated cycle of sin, oppression, crying out and deliverance through judges the LORD raised up (Judg. 2:11–16; 3:9). Judges advances Israel’s redemptive story by showing the nation’s need of a faithful deliverer and a king, and the LORD’s steady mercy toward a people who kept falling away. Its covenant setting is Israel’s, rooted in the oath the LORD swore to the fathers (Judg. 2:1), and the book does not speak of the Mystery. "+CL)
S['ruth'] = ("Israel’s line", "Ruth stands in Israel’s line in the days of the judges, in a short account of Naomi and Ruth the Moabitess (Ruth 1:1, 16). Boaz acts as a near kinsman, redeems the inheritance and takes Ruth, and their son Obed is the father of Jesse, the father of David (Ruth 3:9; 4:10, 17, 22). Ruth advances Israel’s redemptive story by preserving the family line that leads to David, and so toward the king and kingdom promised later. Its law of the kinsman and the inheritance is Israel’s, set in the land, and the book does not speak of the Mystery. "+CL)
S['1samuel'] = ("Israel’s line", "1 Samuel stands in Israel’s line at the turn from the judges to the kings. It moves from Hannah’s prayer and the birth of Samuel to the people’s demand for a king, the anointing and rejection of Saul, and the anointing of David (1 Sam. 1:20; 8:5; 10:1; 15:23; 16:13). The book carries the line toward the throne: the LORD is Israel’s King, and a man after His own heart is set aside for it (1 Sam. 8:7; 13:14). 1 Samuel advances Israel’s redemptive story by bringing David onto the stage, the king through whom the promised kingdom will be established. The monarchy is Israel’s, and the book does not speak of the Mystery. "+CL)
S['2samuel'] = ("Israel’s line", "2 Samuel stands in Israel’s line at the height of the monarchy. David reigns first over Judah and then over all Israel, and the LORD makes His covenant with David through Nathan (2 Sam. 5:3; 7:12–16). The book records the sin with Bathsheba and Nathan’s rebuke, the troubles of David’s house, and his song of praise (2 Sam. 11:27; 12:7, 13; 22:1). 2 Samuel advances Israel’s redemptive story by laying down the promise of an enduring house, throne and kingdom, the promise that later prophets take up. That covenant is made with David and his house, not with the Body, and the book does not speak of the Mystery. "+CL)
S['1kings'] = ("Israel’s line", "1 Kings stands in Israel’s line from David’s last days through Solomon’s throne to the division of the kingdom. It records the building and dedication of the temple, the LORD’s warning to Solomon, the split under Rehoboam, the golden calves, and Elijah’s ministry against Baal (1 Kgs. 6:38; 8:10–11; 9:3–5; 11:11; 12:16, 28; 18:21). 1 Kings advances Israel’s redemptive story in glory and then in judgment: the LORD dwells with Israel in the temple, and the king’s unfaithfulness begins to break the kingdom apart. The temple and throne are Israel’s, and the book does not speak of the Mystery. "+CL)
S['2kings'] = ("Israel’s line", "2 Kings stands in Israel’s line in the years of its judgment. Elijah goes up by a whirlwind and Elisha follows him; then the northern kingdom falls to Assyria and Jerusalem to Babylon (2 Kgs. 2:11; 17:23; 25:1–7). The book gives its own reasons for the fall and closes with a note on Jehoiachin, the house of David still remembered (2 Kgs. 17:7, 18; 25:27–30). 2 Kings advances Israel’s redemptive story by bringing the covenant warnings to their fulfilment, and yet keeping the house of David alive for the promise still to come (2 Kgs. 13:23; 19:34). Its judgment is Israel’s, and the book does not speak of the Mystery. "+CL)
S['1chr'] = ("Israel’s line", "1 Chronicles stands in Israel’s line after the exile, retelling the line from Adam through David for a returned remnant (1 Chr. 1:1; 9:1; 2 Chr. 36:22–23). It carries the line forward in restoration, keeping the house of David, the temple and the covenant before a people who have come back to the land (1 Chr. 16:15–17; 17:11–14). 1 Chronicles advances Israel’s redemptive story by holding the promise to David before the restored remnant, so that the hope of the kingdom is not lost in the return. It does not speak of the Mystery, which was hid in God and not yet revealed (Rom. 16:25; Eph. 3:9). "+CL)
S['2chronicles'] = ("Israel’s line", "2 Chronicles stands in Israel’s line from Solomon’s temple to the decree of Cyrus. It records the glory that fills the house, the LORD’s answer to Solomon, the reforms of Hezekiah and Josiah, the fall of Jerusalem and the proclamation that sends the people home (2 Chr. 7:1, 14; 29:36; 34:33; 36:15–23). 2 Chronicles advances Israel’s redemptive story through judgment to the first step of restoration: the same LORD who carried Judah away stirs up a king to bid them build the house again (2 Chr. 36:22–23). The promises to the temple and the throne are Israel’s, and the book does not speak of the Mystery. "+CL)
S['ezra'] = ("Israel’s line", "Ezra stands in Israel’s line at the return from Babylon. It opens with the decree of Cyrus and follows the people to Jerusalem under Zerubbabel and Jeshua, to the altar, the foundation and the dedication of the house, and then to Ezra the scribe and his prayer of confession (Ezra 1:1–3; 3:2, 10–11; 6:16; 9:6, 15). Ezra advances Israel’s redemptive story by bringing a remnant back to the land to rebuild the house of the LORD, so that the worship of the covenant is restored. The law of Moses Ezra reads and teaches is Israel’s (Ezra 7:6, 10); the Body is not under it (Rom. 6:14). The book does not speak of the Mystery. "+CL)
S['nehemiah'] = ("Israel’s line", "Nehemiah stands in Israel’s line in the time of the restoration. The cupbearer of the king of Persia prays, goes up to Jerusalem, and sees the wall built in fifty and two days (Neh. 1:5; 2:17–18; 6:15). The book carries the line forward in the reading of the book of the law, the confession of the people and the sure covenant sealed with an oath (Neh. 8:1, 8; 9:38; 10:29). Nehemiah advances Israel’s redemptive story by rebuilding the city and renewing the covenant life of the remnant. The wall and the covenant are Israel’s, and the book does not speak of the Mystery. "+CL)
S['esther'] = ("Israel’s line", "Esther stands in Israel’s line among the nations, in the reign of Ahasuerus, when the Jews are scattered through the provinces of the Persian empire (Esth. 1:1; 3:8). Haman seeks to destroy them, Esther goes in to the king, and the decree is answered by a second decree and the days of Purim (Esth. 3:6; 4:16; 9:26). Esther advances Israel’s redemptive story by preserving the people through whom the promises must come, even while they are far from the land. The deliverance is Israel’s, and the book does not speak of the Mystery. "+CL)
S['job'] = ("Outside both lines", "Job stands outside Israel’s line and outside the Mystery. It is set “in the land of Uz” and names no covenant with Israel, no land promise, no tabernacle and no priesthood (Job 1:1). It carries no program forward. It follows a righteous man through loss, the long debate with his friends, the LORD’s answer out of the whirlwind, and his restoration (Job 1:21; 38:1; 42:10). Job advances the redemptive storyline only as testimony: a sufferer who looks for a living Redeemer and finds God just and sovereign over his trial (Job 19:25–27; 42:2). The book does not speak of the Mystery, and it does not place its truths in either program’s line. "+CL)
S['psalms'] = ("Israel’s line", "Psalms stands in Israel’s line as its songbook, in five books of prayer, praise, lament and trust, from the king set on Zion to the songs of the exile (Ps. 2:6; 89:3; 137:1). It carries the line forward in worship: David’s songs, the temple songs, the cry of the captives and the closing praise (Ps. 150:6). Psalms advances Israel’s redemptive story by taking the promises of the covenant, the king and the land into prayer and praise, so that the nation remembers what the LORD has sworn. Its appeals to Zion, the law and the land are Israel’s (Ps. 147:19), and the book does not speak of the Mystery. "+CL)
S['proverbs'] = ("Israel’s line", "Proverbs stands in Israel’s line in the days of Solomon and Hezekiah, the proverbs of Solomon “king of Israel” gathered and copied out for the nation (Prov. 1:1; 25:1). It carries the line forward in wisdom, counsel on the heart, speech, money, friendship and family, all rooted in the fear of the LORD (Prov. 1:7; 31:30). Proverbs advances Israel’s redemptive story by forming a people who walk in the way of the LORD within His covenant,. Where a saying names the Israelite setting, that setting is Israel’s; the book does not speak of the Mystery. "+CL)
S['ecclesiastes'] = ("Israel’s line", "Ecclesiastes stands in Israel’s line as the words of the Preacher, “the son of David, king in Jerusalem” (Eccl. 1:1). He weighs what is done under the sun, declares that all is vanity, and gives a time to every purpose (Eccl. 1:2; 3:1). The book advances Israel’s redemptive story by stripping away every hope that stops at this life and bringing the reader to the fear of God and the coming judgment (Eccl. 12:13–14). The speaker’s setting is Israel’s, and the book does not speak of the Mystery. "+CL)
S['songofsolomon'] = ("Israel’s line", "The Song of Solomon stands in Israel’s line in Solomon’s day, “the song of songs, which is Solomon’s,” sung among the daughters of Jerusalem (Song 1:1; 8:4). It does not carry the promise forward by narrative or prophecy. It sets out faithful love between two lovers: longing and finding, praise of the beloved, and love as strong as death (Song 2:10; 5:16; 8:6–7). The Song advances the redemptive storyline only by showing the LORD’s gift of faithful love in the setting of His people. Its setting is Israel’s, it is not read here as a picture of the Body, and it does not speak of the Mystery. "+CL)
S['isaiah'] = ("Israel’s line", "Isaiah stands in Israel’s line in the days of the kings of Judah, “the vision of Isaiah the son of Amoz, which he saw concerning Judah and Jerusalem” (Isa. 1:1). It carries the line from judgment through the sign of Immanuel and the child born, the comfort of Israel and the Servant who bears iniquity, to the new heavens and the new earth (Isa. 7:14; 9:6; 40:1–3; 53:5–6; 65:17). Isaiah advances Israel’s redemptive story by promising a King and a Servant through whom the nation is restored and the nations come to the light of Zion (Isa. 2:2–3; 42:1; 60:3). The restoration it describes is Israel’s, and the book does not speak of the Mystery. "+CL)
S['jeremiah'] = ("Israel’s line", "Jeremiah stands in Israel’s line at the end of the kingdom of Judah, a prophet “unto the nations” sent to Judah and Jerusalem (Jer. 1:5, 10). It follows his warnings and laments, the siege and fall of Jerusalem, and the promises of the Branch of David and a new covenant (Jer. 23:5; 30:3; 31:31–34; 33:15). Jeremiah advances Israel’s redemptive story by promising restoration after exile and a covenant that writes the law in the heart. That covenant belongs to the house of Israel and the house of Judah (Jer. 31:31); the Body benefits from Christ’s blood without being the covenant party. The book does not speak of the Mystery. "+CL)
S['lamentations'] = ("Israel’s line", "Lamentations stands in Israel’s line at its lowest point: five laments over Jerusalem after its fall, the city sitting solitary that was full of people (Lam. 1:1). In the middle of the ruin the speaker remembers that “it is of the LORD’s mercies that we are not consumed” and that “great is thy faithfulness” (Lam. 3:22–23). Lamentations advances Israel’s redemptive story by carrying the line through judgment into prayer, and by ending with a plea for the LORD to turn them back to Himself (Lam. 5:21). The city, the sanctuary and the people it mourns are Israel’s, and the book does not speak of the Mystery. "+CL)
S['ezekiel'] = ("Israel’s line", "Ezekiel stands in Israel’s line in the exile, a prophet among the captives by the river of Chebar, sent “to the children of Israel, to a rebellious nation” (Ezek. 1:1; 2:3). He is made a watchman, sees the glory depart from the house, and then speaks of the shepherd, the new heart, the valley of bones and a restored temple and land (Ezek. 3:17; 10:18; 34:23; 36:26; 37:1; 40:2; 43:7). Ezekiel advances Israel’s redemptive story by moving from the departure of the glory to its return, and from the scattered house to one nation in the land. The new heart, the nation and the temple are Israel’s (Ezek. 36:24–28; 37:22), and the book does not speak of the Mystery. "+CL)
S['daniel'] = ("Israel’s line", "Daniel stands in Israel’s line at the point of exile. Judah has been carried to Babylon, and the warnings of the Law and the prophets have fallen (Dan. 1:1–2; 9:11–13). The book carries that line forward in judgment and restoration. The kingdoms of the nations rise and fall under God’s rule (Dan. 2:44; 4:35), seventy weeks are fixed on “thy people” and “thy holy city” (Dan. 9:24), and the kingdom is given to the Son of man and the saints (Dan. 7:13–14, 18). Daniel advances Israel’s redemptive story by showing how God preserves His covenant people under judgment and moves them toward the promised kingdom. It does not speak of the Mystery, which was hid in God and not yet revealed (Rom. 16:25; Eph. 3:9). "+CL)
S['hosea'] = ("Israel’s line", "Hosea stands in Israel’s line in the days of the kings of Judah and Jeroboam king of Israel, when the northern kingdom is turning from the LORD (Hos. 1:1). The prophet’s own marriage becomes a picture of the LORD and Israel, and the book speaks of the controversy with the land, Israel called out of Egypt, days without a king, and a return in the latter days (Hos. 3:4–5; 4:1; 11:1). Hosea advances Israel’s redemptive story by bringing the nation’s unfaithfulness to judgment and still promising that Israel will return and seek the LORD and David their king (Hos. 3:5; 14:4). The picture of the LORD and Israel is Israel’s own and is not read here as a picture of the Body. The book does not speak of the Mystery. "+CL)
S['joel'] = ("Israel’s line", "Joel stands in Israel’s line in a day of national calamity, a plague of locusts that becomes a sign of the day of the LORD (Joel 1:4; 1:15; 2:1). The prophet calls for the trumpet in Zion and a turning to the LORD, promises that He will pour out His spirit, and speaks of the gathering of the nations and Judah dwelling for ever (Joel 2:12–13, 28–32; 3:2, 20). Joel advances Israel’s redemptive story by carrying it through the day of the LORD to deliverance in Zion and the LORD dwelling among His people (Joel 2:32; 3:17, 21). The day, the deliverance and the dwelling it describes are Israel’s and the nations’, and the book does not speak of the Mystery. "+CL)
S['amos'] = ("Israel’s line", "Amos stands in Israel’s line in the days of the divided kingdom, a herdman of Tekoa sent to “my people Israel” (Amos 1:1; 7:15). The LORD roars from Zion, judges the nations around and then Israel itself, and sends a famine of hearing the word (Amos 1:2; 3:2; 8:11). Amos advances Israel’s redemptive story by carrying it through judgment to the raising up of the tabernacle of David and the planting of Israel upon their land, never to be pulled up again (Amos 9:11, 14–15). The judgment and the restoration are Israel’s, and the book does not speak of the Mystery. "+CL)
S['obadiah'] = ("Israel’s line", "Obadiah stands in Israel’s line as a single chapter, the vision against Edom, the brother of Jacob (Obad. 1, 10). Pride in the clefts of the rock is brought down, the day of the LORD is near upon all the heathen, and deliverance comes on mount Zion (Obad. 3–4, 15, 17). Obadiah advances Israel’s redemptive story by promising judgment on the nation that wronged Jacob and ending with the line that “the kingdom shall be the LORD’s” (Obad. 21). The judgment, the deliverance and the kingdom it names are Israel’s, and the book does not speak of the Mystery. "+CL)
S['jonah'] = ("Israel’s line", "Jonah stands in Israel’s line as the story of a prophet of the LORD sent from Israel’s side of the sea to a Gentile city. Jonah speaks of himself as a Hebrew and looks toward the LORD’s holy temple (Jonah 1:1–2, 9; 2:4). He flees, is carried by the fish the LORD prepared, preaches in Nineveh, and is answered by the city’s turning and the LORD’s closing question (Jonah 1:17; 3:4–10; 4:11). Jonah advances Israel’s redemptive story by showing the LORD’s mercy reaching a city that repents, through an Israelite prophet who is slow to share it. His errand is Israel’s prophetic mission to a Gentile city; it is not Paul’s commission, and the book does not speak of the Mystery. "+CL)
S['micah'] = ("Israel’s line", "Micah stands in Israel’s line in the days of Jotham, Ahaz and Hezekiah, a prophet who saw the word “concerning Samaria and Jerusalem” (Mic. 1:1). He speaks judgment on both cities, promises that “in the last days” the mountain of the house of the LORD will be established, and names the ruler to come out of Bethlehem (Mic. 4:1–2; 5:2). Micah advances Israel’s redemptive story by promising a remnant, a ruler and a kingdom, and ending in a prayer to the God who pardons iniquity (Mic. 5:3, 7; 7:18–20). The ruler, the remnant and the kingdom are Israel’s, and the book does not speak of the Mystery. "+CL)
S['nahum'] = ("Israel’s line", "Nahum stands in Israel’s line in the burden of Nineveh, a word of judgment on the capital of the empire that had troubled Judah (Nah. 1:1). It describes the LORD slow to anger, great in power and good to those who trust in Him, the fall of the city, and good tidings for Judah (Nah. 1:3, 7, 15; 3:7, 19). Nahum advances Israel’s redemptive story by showing the LORD judging the nation that oppressed His people and bringing good tidings to Judah (Nah. 1:15). The deliverance is Israel’s, the verses on the LORD’s character reach every reader, and the book does not speak of the Mystery. "+CL)
S['habakkuk'] = ("Israel’s line", "Habakkuk stands in Israel’s line as Judah faces the coming of the Chaldeans, a prophet who brings his complaint to the LORD and waits for an answer (Hab. 1:1, 5, 13). The LORD tells him to write the vision for an appointed time and that “the just shall live by his faith” (Hab. 2:2–4). Habakkuk advances Israel’s redemptive story by teaching the nation to wait in faith while judgment comes, and by ending in rejoicing even if the fig tree does not blossom (Hab. 3:17–19). The vision and the people it speaks for are Israel’s, and the book does not speak of the Mystery. "+CL)
S['zephaniah'] = ("Israel’s line", "Zephaniah stands in Israel’s line in the days of Josiah, king of Judah, with a word on the great day of the LORD (Zeph. 1:1, 14). The prophet calls the meek to seek the LORD, promises a pure language, an afflicted and poor people who trust in His name, and the song of the daughter of Zion (Zeph. 2:3; 3:9, 12, 14–17). Zephaniah advances Israel’s redemptive story by carrying it through the day of the LORD to a preserved remnant and the king of Israel in their midst (Zeph. 3:13–15). The day, the remnant and the king are Israel’s, and the book does not speak of the Mystery. "+CL)
S['haggai'] = ("Israel’s line", "Haggai stands in Israel’s line in the time of the return, four words of the LORD by the prophet to Zerubbabel the governor and Joshua the high priest (Hag. 1:1). The people are told to consider their ways and build the house, and the LORD promises to be with them and to fill the house with glory (Hag. 1:5, 8; 2:4, 7, 9). Haggai advances Israel’s redemptive story by calling the remnant to restore the worship of the LORD and by promising a shaking of the heavens, the earth and the nations, with Zerubbabel as a signet (Hag. 2:6–7, 21–23). The house, the covenant from Egypt and the promise are Israel’s, and the book does not speak of the Mystery. "+CL)
S['zechariah'] = ("Israel’s line", "Zechariah stands in Israel’s line after the return, a word of the LORD in the second year of Darius (Zech. 1:1). It moves through night visions, the high priest and the BRANCH, and the King who comes lowly on an ass, to the house of David mourning for the one they pierced, and the day when the LORD stands on the mount of Olives and is king over all the earth (Zech. 3:8; 9:9; 12:10; 14:4, 9). Zechariah advances Israel’s redemptive story by showing the King, the cleansing and the kingdom set in Jerusalem, with the nations coming up to worship (Zech. 13:1; 14:16). The King, the city and the kingdom are Israel’s, and the book does not speak of the Mystery. "+CL)
S['malachi'] = ("Israel’s line", "Malachi stands at the close of the Old Testament prophets, “the burden of the word of the LORD to Israel” (Mal. 1:1). It reproves the priests, charges Judah with treachery against the covenant of the fathers, calls for the tithes, records a book of remembrance for those who feared the LORD, and ends with the day that burns as an oven and the promise of Elijah the prophet (Mal. 2:10; 3:10, 16; 4:1, 5). Malachi advances Israel’s redemptive story by calling the nation back to the covenant and leaving it watching for the forerunner and the day of the LORD (Mal. 3:1; 4:2, 4–6). The covenant, the priesthood and the day are Israel’s, and the book does not speak of the Mystery. "+CL)
S['matthew'] = ("Israel’s line", "Matthew stands in Israel’s line at the point where the promise is met in the person of the King. It opens with “the son of David, the son of Abraham,” and shows Jesus fulfilling the prophets (Matt. 1:1, 22; 2:15, 23). The book carries that line through the announcement that the kingdom of heaven is at hand, the Lord’s ministry to “the lost sheep of the house of Israel,” His rejection, and the cross and empty tomb (Matt. 4:17; 10:5–6; 15:24; 20:28; 28:6). Matthew advances Israel’s redemptive story by presenting the King of Israel, His offer of the kingdom to the nation, and the giving of His life as a ransom for many. The kingdom it announces is Israel’s, and the book does not set out the Mystery, which was hid in God and later made known through Paul. "+CL)
S['mark'] = ("Israel’s line", "Mark stands in Israel’s line at the coming of the King, “the beginning of the gospel of Jesus Christ, the Son of God” (Mark 1:1). The Lord comes into Galilee “preaching the gospel of the kingdom of God,” teaches with authority, is confessed by Peter as the Christ, and is crucified under the superscription “THE KING OF THE JEWS” (Mark 1:14–15, 22; 8:29; 15:26). Mark advances Israel’s redemptive story by showing the Servant-King giving His life “a ransom for many” and rising from the dead (Mark 10:45; 16:6). The kingdom gospel it carries is Israel’s, and the book does not set out the Mystery, which was hid in God and later made known through Paul. "+CL)
S['luke'] = ("Israel’s line", "Luke stands in Israel’s line at the coming of the King, written “in order” that the reader might know the certainty of what he had been taught (Luke 1:1–4). The angel promises that the Lord God will give the Son “the throne of his father David,” good tidings come to the city of David, and the Lord preaches “the acceptable year of the Lord” (Luke 1:32–33; 2:10–11; 4:19). The book follows the road to Jerusalem, the cup of the new testament, and the risen Lord appearing to His own (Luke 9:51; 22:20; 24:36–47). Luke advances Israel’s redemptive story by presenting the Son of David, His death and resurrection, and the promise of the thrones for the Twelve (Luke 22:29–30). The throne and the twelve tribes it names are Israel’s, and the book does not set out the Mystery, which was hid in God and later made known through Paul. "+CL)
S['john'] = ("Israel’s line", "John stands in Israel’s line at the coming of the Word made flesh, who came to “his own” (John 1:1, 11, 14). The Baptist is sent that the Lord should be made manifest to Israel, and Nathanael confesses Him the King of Israel (John 1:31, 49). The book carries the line through the signs, the feasts at Jerusalem, the raising of Lazarus, the King’s entry, the cross and the empty tomb (John 2:11; 11:43–44; 12:13; 19:30; 20:31). John advances Israel’s redemptive story by presenting the Lamb of God and the Son of God, so that those who believe might have life in His name (John 1:29; 20:31). Its audience is Israel, and the book does not set out the Mystery, which was hid in God and later made known through Paul. "+CL)
S['acts'] = ("Both lines, side by side", "Acts stands at the hinge of the two lines and runs both. Chapters 1–8 belong to Israel’s line: the risen Lord speaks of the kingdom, the disciples ask whether He will restore it to Israel, and the witness goes out from Jerusalem (Acts 1:3, 6, 8). With chapter 9 the Lord calls Saul, and Paul’s ministry begins; chapters 9–28 are the overlap, in which Paul’s gospel forms the Body while Israel’s line remains operative until its national suspension at Acts 28 (Acts 9:15; 28:17–31). Acts advances each line in its own track: Israel’s redemptive story through the renewed witness to the nation and its suspension, and the Mystery’s through the calling and commission of Paul. It does not blend the two, and events in Acts 9–28 are reported as written, not assigned to a single program. "+CL)
S['romans'] = ("The Mystery line", "Romans stands in the Mystery that Paul received by revelation (Rom. 16:25–26) and was sent to preach to the Gentiles (Rom. 11:13). It was written during Acts 9–28, while Israel’s line ran alongside. It advances the revelation of righteousness by faith (Rom. 3:21–26), of life in the Spirit (Rom. 8), and of the walk that follows (Rom. 12–15). Romans advances the Mystery’s redemptive provision by setting out justification, sanctification, and the Spirit-empowered life for the Body of Christ. Chapters 9–11 speak of Israel’s future, but they do not make the Body part of Israel’s line or a party to its covenants. Participation is not identity. Blessing is not covenant. Standing is not program membership. "+CL)
S['1corinthians'] = ("The Mystery line", "1 Corinthians stands in the Mystery line, in a letter from Paul to a Gentile church written during the Acts 9–28 overlap, in answer to reports of divisions and to questions the Corinthians had sent (1 Cor. 1:1–2, 11; 7:1). He holds that a dispensation of the gospel is committed to him (1 Cor. 9:17). The letter orders the life of the assembly: factions, discipline, marriage, worship, spiritual gifts and the collection (1 Cor. 5:1–5; 7:1; 12:1; 16:1–2). 1 Corinthians advances the Mystery’s redemptive provision by setting out the gospel Paul preached, that Christ died for our sins, was buried and rose again (1 Cor. 15:1–4), and the resurrection hope of the Body (1 Cor. 15:51–52). The letter is read for what it says to the Body; the Body is not made a party to Israel’s covenants, and the book is not read as Israel’s program. "+CL)
S['2corinthians'] = ("The Mystery line", "2 Corinthians stands in the Mystery line, in Paul’s second letter to a Gentile church during the Acts 9–28 overlap, written about his affliction and comfort, his change of plans and the defense of his apostleship (2 Cor. 1:1, 3–4; 11:5; 12:12). It carries the line through the ministry of reconciliation, the new creation in Christ, and the collection for the saints (2 Cor. 5:17–21; 8:1–4; 9:1). 2 Corinthians advances the Mystery’s redemptive provision by showing that God was in Christ reconciling the world to Himself and has committed to Paul the word of reconciliation (2 Cor. 5:19). The new covenant belongs to the house of Israel and the house of Judah (Jer. 31:31–34); the Body benefits from Christ’s blood without being the covenant party. "+CL)
S['galatians'] = ("The Mystery line", "Galatians stands in the Mystery line, in Paul’s defense of the gospel committed to him, written to the churches of Galatia because believers were turning to “another gospel” (Gal. 1:1–2, 6–7, 11–12). He recounts the agreement that Peter had the gospel of the circumcision and he of the uncircumcision (Gal. 2:7–9). The letter argues justification by faith apart from the works of the law, and that the believer lives by faith in the Son of God (Gal. 2:16, 20; 3:11). Galatians advances the Mystery’s redemptive provision by guarding the gospel of grace from any admixture of law. The seed is prophetic fulfillment in Christ; the Body receives blessing through Christ alone, not through participation in the Abrahamic covenant. The two ministries it names run alongside each other and do not merge. "+CL)
S['ephesians'] = ("The Mystery line", "Ephesians stands in the Mystery line, in the letter where Paul sets out the mystery most fully, written as “the prisoner of the Lord” to Gentile believers in Christ (Eph. 1:1; 3:1–9; 4:1). The mystery was hid in God from the beginning of the world and made known through Paul: Jew and Gentile one body in Christ, seated in heavenly places (Eph. 2:6, 11–16; 3:2–9). Ephesians advances the Mystery’s redemptive provision by showing the Body’s redemption through His blood, its union with Christ, and the walk that fits the calling (Eph. 1:7; 2:8–9; 4:1). Its readers were once aliens from the commonwealth of Israel and strangers from the covenants of promise (Eph. 2:12). The Body is not Israel and is not a party to Israel’s covenants, and the wall of the law is abolished for the Body (Eph. 2:14–15). "+CL)
S['philippians'] = ("The Mystery line", "Philippians stands in the Mystery line, in Paul’s letter from prison to the saints in Christ Jesus at Philippi, with its thanks for their gift and its report of his circumstances (Phil. 1:1, 7, 13; 4:10–18). It sets before them the mind of Christ, who humbled Himself and was exalted, and a citizenship in heaven (Phil. 2:5–11; 3:20). Philippians advances the Mystery’s redemptive provision by showing the life that follows the Body’s salvation: to know Christ, His righteousness and the power of His resurrection (Phil. 3:8–10). Paul counts his own Israelite standing as loss for Christ (Phil. 3:4–8), and the letter does not make the Body a party to Israel’s covenants. "+CL)
S['colossians'] = ("The Mystery line", "Colossians stands in the Mystery line, in Paul’s letter from bonds to the saints and faithful brethren in Christ at Colosse (Col. 1:1–2; 4:3, 18). It speaks of the mystery hid from ages and generations and now made manifest to the saints, Christ in you, the hope of glory (Col. 1:26–27). The letter warns against philosophy, tradition and ordinances that would take believers from Christ (Col. 2:8, 16–17). Colossians advances the Mystery’s redemptive provision by showing Christ as head over all and sufficient for the Body: redemption through His blood, and completeness in Him (Col. 1:14–18; 2:9–10). The festivals, new moons and sabbath days it names are a shadow of things to come, and the Body is not held to them (Col. 2:16–17). "+CL)
S['1thessalonians'] = ("The Mystery line", "1 Thessalonians stands in the Mystery line, in Paul’s letter with Silvanus and Timotheus to a young church of believers, recalling how they received the gospel and turned from idols (1 Thess. 1:1, 9). It gives instruction on holy living, comfort about those who sleep, and the day of the Lord (1 Thess. 4:3, 13–18; 5:1–3). 1 Thessalonians advances the Mystery’s redemptive provision by setting before the Body its hope: the Lord’s descent from heaven, the dead in Christ rising and the living caught up together with them (1 Thess. 4:16–17). It says that God has not appointed them to wrath (1 Thess. 5:9). The hope it gives is the Body’s own, and the letter does not make the Body a party to Israel’s covenants. "+CL)
S['2thessalonians'] = ("The Mystery line", "2 Thessalonians stands in the Mystery line, in Paul’s second letter with Silvanus and Timotheus to believers suffering persecution (2 Thess. 1:1, 4). He thanks God for their growing faith, writes of the Lord’s revelation from heaven, corrects a worry about the day of Christ, and gives directions about the idle (2 Thess. 1:3, 7; 2:1–3; 3:6–12). 2 Thessalonians advances the Mystery’s redemptive provision by steadying a persecuted church: it sets out what must come before the day it names, and calls the believers to stand fast and hold the traditions they were taught (2 Thess. 2:3, 15). The letter belongs to the Body and does not make the Body a party to Israel’s covenants. "+CL)
S['1timothy'] = ("The Mystery line", "1 Timothy stands in the Mystery line, in a letter from Paul to Timothy, “my own son in the faith,” whom he left at Ephesus to charge certain men that they teach no other doctrine (1 Tim. 1:2–3). It sets out sound doctrine, prayer, the qualifications of overseers and deacons, and godliness (1 Tim. 2:1–2; 3:1–13; 4:7–8). 1 Timothy advances the Mystery’s redemptive provision by guarding the order and doctrine of the assembly and affirming that “Christ Jesus came into the world to save sinners” (1 Tim. 1:15). The church order it gives is the Body’s own; it sets no Israelite priesthood, temple or covenant duty on the Body. "+CL)
S['2timothy'] = ("The Mystery line", "2 Timothy stands in the Mystery line, in Paul’s last letter in the pastoral group, written from prison near the end of his course to Timothy, “my dearly beloved son” (2 Tim. 1:2; 4:6–8). He urges Timothy to stir up the gift of God, to endure hardness, to hold the form of sound words and to preach the word (2 Tim. 1:6, 13; 2:3; 4:2). 2 Timothy advances the Mystery’s redemptive provision by passing the gospel on to faithful men and showing that grace was given in Christ Jesus before the world began (2 Tim. 1:9–10; 2:2; 3:16–17). The letter’s warnings and commands are given to a minister of the Body, and it sets no Israelite covenant duty on the Body. "+CL)
S['titus'] = ("The Mystery line", "Titus stands in the Mystery line, in a letter from Paul to Titus, “mine own son after the common faith,” whom he left in Crete to set in order the things that were wanting and ordain elders in every city (Titus 1:1, 4–5). It gives the qualifications of elders, sound teaching for each group, and the grace of God that brings salvation (Titus 1:5–9; 2:1–10; 2:11–14). Titus advances the Mystery’s redemptive provision by showing that salvation is not by works of righteousness but by His mercy, and by joining sound doctrine to good works (Titus 3:5–8). The order and conduct it gives are the Body’s own, and it sets no Israelite covenant duty on the Body. "+CL)
S['philemon'] = ("The Mystery line", "Philemon stands in the Mystery line, in a short letter from Paul, a prisoner of Jesus Christ, to Philemon, Apphia, Archippus and the church in his house (Philem. 1–2). He appeals for Onesimus, whom he calls his son begotten in his bonds, and asks Philemon to receive him as a brother beloved (Philem. 10, 16). Philemon advances the Mystery’s redemptive provision by showing its fruit in a single household: love, reconciliation and fellowship between believers. The letter sets out no new doctrine and gives no Israelite covenant duty to the Body. "+CL)
S['hebrews'] = ("Israel’s line", "Hebrews stands in Israel’s line, in a letter to Hebrew believers that opens with God having spoken in time past to the fathers by the prophets and “in these last days” by His Son (Heb. 1:1–2). It sets the Son above the angels, above Moses and above the Levitical priesthood, and speaks of a better covenant, a better sanctuary and a better sacrifice (Heb. 1:4; 3:3; 7:11–12; 8:6; 9:12). Hebrews advances Israel’s redemptive story by showing how the covenant of Jeremiah 31 rests on the blood of the Son and by calling its readers to hold fast and run with patience (Heb. 8:8–12; 10:19–23; 12:1). That covenant belongs to the house of Israel and the house of Judah; the Body benefits from Christ’s blood without being the covenant party. The letter does not set out the Mystery. "+CL)
S['james'] = ("Israel’s line", "James stands in Israel’s line, in a letter from James, “a servant of God and of the Lord Jesus Christ, to the twelve tribes which are scattered abroad” (James 1:1). It speaks of trials, wisdom, doing the word, faith and works, the tongue and patience until the coming of the Lord (James 1:2–5, 22; 2:14–26; 3:5–8; 5:7–8). James advances Israel’s redemptive story by instructing the scattered tribes how to live the word in their trials while they wait for the Lord’s coming (James 5:7–8). Its commands, including its faith-and-works argument and its instructions for the sick, are addressed to the twelve tribes and are not carried over to the Body (James 5:14). The letter does not set out the Mystery. "+CL)
S['1peter'] = ("Israel’s line", "1 Peter stands in Israel’s line, in a letter from Peter, the apostle named in Galatians as having the gospel of the circumcision, to the strangers scattered through Pontus, Galatia, Cappadocia, Asia and Bithynia (1 Pet. 1:1; Gal. 2:7–9). It speaks of a lively hope, an inheritance reserved in heaven, the trial of faith, holy conduct, submission and suffering for well doing (1 Pet. 1:3–7; 2:9, 13–15; 3:14–17). 1 Peter advances Israel’s redemptive story by setting the sufferings of Christ and the glory that follows before a scattered people, and calling them to hope to the end for the grace brought at the revelation of Jesus Christ (1 Pet. 1:10–13; 5:1). The letter does not set out the Mystery, and its promises to a chosen generation and royal priesthood are not carried over to the Body. "+CL)
S['2peter'] = ("Israel’s line", "2 Peter stands in Israel’s line, in Peter’s second letter to the same readers as the first, written by one who knows that he must shortly put off his tabernacle (2 Pet. 1:1, 13–14; 3:1). 2 Peter advances Israel’s redemptive story by holding the prophetic hope before the scattered believers and calling them to grow in grace and to look for new heavens and a new earth (2 Pet. 3:13, 18). The letter does not set out the Mystery. "+CL)
S['jude'] = ("Israel’s line", "Jude stands in Israel’s line, in a short letter from Jude, the servant of Jesus Christ and brother of James, to those who are sanctified, preserved in Jesus Christ and called (Jude 1). He had meant to write of the common salvation and found it needful to urge his readers to contend for the faith once delivered to the saints (Jude 3). The letter speaks of men crept in unawares, examples of judgment, Enoch’s prophecy and the words of the apostles (Jude 4–7, 14–18). Jude advances Israel’s redemptive story by guarding the faith against corruption and pointing to the Lord’s coming with His saints and the mercy unto eternal life (Jude 14, 21). The letter does not set out the Mystery. "+CL)
S['1john'] = ('Israel’s line', '1 John stands in Israel’s line, in a letter that does not name its author and speaks to its readers as “my little children” and “beloved” (1 John 2:1; 3:2). It begins with the Word of life, which was from the beginning, heard, seen and handled (1 John 1:1–2). The letter speaks of fellowship, walking in the light, sin and forgiveness, love, antichrists and the new birth (1 John 1:3, 7, 9; 2:18; 4:7; 5:1). 1 John advances Israel’s redemptive story by tying fellowship, love and belief to the Son sent as the propitiation for our sins, and to the eternal life given in Him (1 John 4:9–10; 5:11–13). The letter does not set out the Mystery. '+CL)
S['2john'] = ('Israel’s line', '2 John stands in Israel’s line, in a short letter from the elder to “the elect lady and her children” (2 John 1). It speaks of truth, love, walking after His commandments, deceivers who confess not that Jesus Christ is come in the flesh, and the doctrine of Christ (2 John 4–7, 9–10). 2 John advances Israel’s redemptive story by holding to the Son who came in the flesh and guarding the truth about Him against those who would turn the readers aside. The letter does not set out the Mystery. '+CL)
S['3john'] = ('Israel’s line', '3 John stands in Israel’s line, in a personal letter from the elder to “the wellbeloved Gaius” (3 John 1). It speaks of walking in the truth, faithful service to the brethren and to strangers, the pride of Diotrephes, and the good report of Demetrius (3 John 3–6, 9, 12). 3 John advances Israel’s redemptive story in the small: it shows the truth lived out in hospitality toward those who went forth for His name’s sake (3 John 7–8). Its call to follow what is good and not what is evil reaches every reader (3 John 11), and the letter does not set out the Mystery. '+CL)
S['revelation'] = ("Israel’s line", "Revelation stands at the close of Israel’s prophetic line, where the promises of the Law and the prophets come to their end (Rev. 1:7; Zech. 12:10). It carries that line through judgment (Rev. 6–19), the return of Christ (Rev. 19:11–16), the reign of the thousand years (Rev. 20:4–6), and the new creation (Rev. 21:1–4). Revelation advances Israel’s redemptive story by bringing its promised restoration, kingdom glory, and final renewal to completion. The Body of Christ does not appear in its scenes, the great multitude of Revelation 7:9 is not the Body, and the book does not set out the Mystery. "+CL)
